/**
 * bug 6073 验证：打开 单元管理 → 单元信息 详情，核对「房屋范围」工具栏只剩 房屋选择/删除，无「单元拆分」。
 * 使用 8099 独立验证站点（本任务 worktree 构建产物），不影响 8098。
 */
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const authPath = path.resolve(__dirname, '../.auth/zsbase-auto.json')
const outDir = path.resolve(__dirname, '../../../.pua/shots')
fs.mkdirSync(outDir, { recursive: true })

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const user = process.env.PLAYWRIGHT_LOGIN_USER || 'zsbase'
const pass = process.env.PLAYWRIGHT_LOGIN_PASSWORD || 'ZS001Aa!'

const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')
const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1600, height: 1000 }, storageState: fs.existsSync(authPath) ? authPath : undefined })
const page = await ctx.newPage()
page.setDefaultTimeout(30000)

const log = (...a) => console.log(...a)

await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(2000)
if ((page.url() || '').includes('/login')) {
  log('需要登录，抓验证码')
  await page.waitForSelector('.login-code img')
  await page.waitForTimeout(800)
  const png = path.join(outDir, 'login-captcha-6073.png')
  await page.locator('.login-code img').screenshot({ path: png })
  log('CAPTCHA_IMG', png)
  log('ARGV_HINT', 'node verify-bug6073.mjs --code XXXX')
  const i = process.argv.indexOf('--code')
  const code = i > -1 ? process.argv[i + 1] : ''
  if (!code) { await browser.close(); process.exit(0) }
  const inputs = page.locator('.login-form input')
  await inputs.nth(0).fill(user)
  await inputs.nth(1).fill(pass)
  await inputs.nth(2).fill(code)
  await page.locator('.login-button').click()
  await page.waitForFunction(() => !(window.location.hash || '').includes('/login'), { timeout: 45000 })
  log('LOGIN OK')
  await page.waitForTimeout(1500)
  fs.mkdirSync(path.dirname(authPath), { recursive: true })
  await ctx.storageState({ path: authPath })
  log('STORAGE saved')
}

const dumpHash = await page.evaluate(() => window.location.hash)
log('CURRENT_HASH', dumpHash)

// 打开单元管理列表
await page.goto('/#/projectManagement/unitinfo/index', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(2500)
await page.screenshot({ path: path.join(outDir, '6073-01-list.png'), fullPage: false })

const rows = await page.locator('.el-table__body-wrapper tbody tr').count()
log('LIST_ROWS', rows)
if (!rows) { log('列表无数据，无法进入详情'); await browser.close(); process.exit(0) }

// 第一行点「查看」
const viewBtn = page.locator('.el-table__body-wrapper tbody tr').first().getByText('查看', { exact: true }).first()
if (await viewBtn.count()) { await viewBtn.click() } else {
  const anyBtn = page.locator('.el-table__body-wrapper tbody tr').first().locator('button').first()
  await anyBtn.click()
}
await page.waitForTimeout(2500)
log('DETAIL_HASH', await page.evaluate(() => window.location.hash))
await page.waitForTimeout(1000)
await page.screenshot({ path: path.join(outDir, '6073-02-detail.png'), fullPage: true })

// 定位「房屋范围」区块工具栏
const toolbar = page.locator('.operation-button-container').first()
const btnTexts = await page.locator('.operation-button-container button').allInnerTexts()
log('TOOLBAR_BUTTONS', JSON.stringify(btnTexts.map((s) => s.trim())))
const hasSplit = btnTexts.some((s) => s.includes('单元拆分'))
log('HAS_UNIT_SPLIT', hasSplit)

// 全页文本再核对
const pageText = await page.evaluate(() => document.body.innerText)
log('PAGE_HAS_SPLIT_TEXT', pageText.includes('单元拆分'))

await browser.close()
log('DONE')

