import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const authPath = path.resolve(__dirname, '../.auth/zsbase-auto.json')
const outDir = path.resolve(__dirname, '../../../.pua/shots')
fs.mkdirSync(outDir, { recursive: true })

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const user = process.env.PLAYWRIGHT_LOGIN_USER || 'zsbase'
const pass = process.env.PLAYWRIGHT_LOGIN_PASSWORD || 'ZS001Aa!'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')

const i = process.argv.indexOf('--code')
const code = i > -1 ? process.argv[i + 1] : ''

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1600, height: 1000 } })
const page = await ctx.newPage()
page.setDefaultTimeout(20000)

// 抓取 /code 响应里的 uuid
let lastUuid = ''
page.on('response', async (r) => {
  const u = r.url()
  if (u.endsWith('/code')) {
    try {
      const j = await r.json()
      if (j && j.uuid) { lastUuid = j.uuid }
    } catch { /* ignore */ }
  }
  if (u.includes('userLogin')) {
    try { const t = await r.text(); console.log('LOGIN_RESP', t.slice(0, 400)) } catch { /* */ }
  }
})

await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.login-form input', { timeout: 30000 })
await page.waitForTimeout(2500)

if (!code) {
  const png = path.join(outDir, 'login-captcha-6073.png')
  await page.locator('.login-code img').screenshot({ path: png })
  console.log('CAPTCHA_IMG', png)
  const uuidInStore = await page.evaluate(() => {
    const el = document.querySelector('.login-code img')
    return el ? el.getAttribute('src').slice(0, 40) : 'none'
  })
  console.log('CODE_SRC_PREFIX', uuidInStore)
  console.log('UUID_FROM_RESPONSE', lastUuid)
  await browser.close()
  process.exit(0)
}

console.log('CAPTCHA_FROM_PREVIOUS_LOAD', 'uuid=', lastUuid)

// 手动通过页面 fetch（走应用同一加密链路不可行），改为：直接用页面已加载的 uuid + 输入框提交
const inputs = page.locator('.login-form input')
await inputs.nth(0).fill(user)
await inputs.nth(1).fill(pass)
await inputs.nth(2).fill(code)
await page.waitForTimeout(200)
await page.locator('.login-button, button:has-text("登录")').first().click()

try {
  await page.waitForFunction(() => !(window.location.hash || '').includes('/login'), { timeout: 30000 })
  console.log('LOGIN OK hash=', await page.evaluate(() => window.location.hash))
  await page.waitForTimeout(2000)
  fs.writeFileSync(authPath, JSON.stringify(await ctx.storageState(), null, 2))
  console.log('STORAGE saved', authPath)
} catch {
  const tip = await page.evaluate(() => document.body.innerText.slice(0, 400).replace(/\n+/g, ' | '))
  console.log('LOGIN FAILED BODY:', tip)
}
await browser.close()

import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const authPath = path.resolve(__dirname, '../.auth/zsbase-auto.json')
const outDir = path.resolve(__dirname, '../../../.pua/shots')
const capPath = path.join(outDir, 'captcha-current.png')
fs.mkdirSync(outDir, { recursive: true })

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const user = process.env.PLAYWRIGHT_LOGIN_USER || 'zsbase'
const pass = process.env.PLAYWRIGHT_LOGIN_PASSWORD || 'ZS001Aa!'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1600, height: 1000 } })
const page = await ctx.newPage()
page.setDefaultTimeout(20000)

let codeB64 = ''
let uuid = ''
page.on('response', async (r) => {
  const u = r.url()
  if (u.endsWith('/code')) {
    try { const j = await r.json(); if (j && j.data) { codeB64 = j.data; uuid = j.uuid } } catch { /* */ }
  }
  if (u.includes('userLogin')) {
    try { console.log('LOGIN_RESP', (await r.text()).slice(0, 200)) } catch { /* */ }
  }
})

await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.login-form input', { timeout: 30000 })
await page.waitForTimeout(2500)

// 把服务端原图落盘（与页面 <img> 同源）
if (codeB64) fs.writeFileSync(capPath, Buffer.from(codeB64, 'base64'))
console.log('CAPTCHA_IMG', capPath, 'uuid=', uuid)
console.log('READY: 识别后执行  node e2e/scripts/login3-6073.mjs --code <答案>')
if (process.argv.includes('--solve')) {
  // 直接在本进程内等一会儿不便；提供 --code 分支在下面
}
const i = process.argv.indexOf('--code')
const ans = i > -1 ? process.argv[i + 1] : ''
console.log('ARG_CODE_PRESENT', JSON.stringify(ans))
fs.writeFileSync(path.join(outDir, 'captcha-state.json'), JSON.stringify({ uuid, codeB64Len: codeB64.length }))
await browser.close()

/**
 * 同进程内完成「取验证码 → 人工识别 → 用页面自身链路登录」：
 * 通过 page.evaluate 调用页面内 axios 不可行（模块作用域），
 * 因此改为：输入账号密码后，直接点登录按钮，并在同一页面会话内保持 uuid 与图片一致。
 * 关键：先取图（--capture），识别后立即在「同一浏览器上下文」提交，uuid 才不会失效。
 * 做法：一次运行内先截图 → 读取由参数传入的答案 → 立刻提交。答案通过环境变量 CAPTCHA_ANSWER 传入，
 * 图片保存为 outDir/live-captcha.jpg 供人工在该进程等待期间识别。
 */
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import readline from 'readline'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const authPath = path.resolve(__dirname, '../.auth/zsbase-auto.json')
const outDir = path.resolve(__dirname, '../../../.pua/shots')
fs.mkdirSync(outDir, { recursive: true })

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const user = process.env.PLAYWRIGHT_LOGIN_USER || 'zsbase'
const pass = process.env.PLAYWRIGHT_LOGIN_PASSWORD || 'ZS001Aa!'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1600, height: 1000 } })
const page = await ctx.newPage()
page.setDefaultTimeout(20000)

page.on('response', async (r) => {
  const u = r.url()
  if (u.includes('userLogin')) {
    try { console.log('LOGIN_RESP', (await r.text()).slice(0, 200)) } catch { /* */ }
  }
})

await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.login-form input', { timeout: 30000 })
await page.waitForTimeout(2500)

// 用页面展示的验证码图片（与图片对应的 uuid 已在页面 state 内），截图后等待人工输入
const liveCap = path.join(outDir, 'live-captcha.png')
await page.locator('.login-code img').screenshot({ path: liveCap })
console.log('LIVE_CAPTCHA', liveCap)

const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
const ans = await new Promise((resolve) => {
  rl.question('INPUT_CAPTCHA> ', (a) => { rl.close(); resolve(a.trim()) })
})
console.log('ANSWER', ans)

const inputs = page.locator('.login-form input')
await inputs.nth(0).fill(user)
await inputs.nth(1).fill(pass)
await inputs.nth(2).fill(ans)
await page.waitForTimeout(200)
await page.locator('.login-button, button:has-text("登录")').first().click()

try {
