tool_input.content:
/**
 * bug 6073 端到端验证（含人工验证码识别）。
 *
 * 由于登录验证码在页面内存态里（uuid 与图片绑定），不能跨进程复用，
 * 本脚本在单个浏览器上下文内：取图 -> 保存 -> 等人工在终端输入答案 -> 提交 -> 落 storageState
 * -> 直接进入 单元管理/单元信息 详情 -> 采集「房屋范围」工具栏按钮文本 -> 截图。
 *
 * 运行： node e2e/scripts/verify6073-e2e.mjs  (交互输入验证码)
 */
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import readline from 'readline'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const authPath = path.resolve(__dirname, '../.auth/zsbase-auto.json')
const outDir = path.resolve(__dirname, '../../../.pua/shots')
fs.mkdirSync(outDir, { recursive: true })

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const user = process.env.PLAYWRIGHT_LOGIN_USER || 'zsbase'
const pass = process.env.PLAYWRIGHT_LOGIN_PASSWORD || 'ZS001Aa!'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1680, height: 1000 } })
const page = await ctx.newPage()
page.setDefaultTimeout(30000)

page.on('response', async (r) => {
  const u = r.url()
  if (u.includes('/menu/')) console.log('MENU_RESP', r.status(), u.replace(baseURL, ''))
})

await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.login-form input', { timeout: 30000 })
await page.waitForTimeout(2200)

const liveCap = path.join(outDir, 'live-captcha.png')
await page.locator('.login-code img').screenshot({ path: liveCap })
console.log('LIVE_CAPTCHA', liveCap)

const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
const ans = await new Promise((resolve) => { rl.question('INPUT_CAPTCHA> ', (a) => { rl.close(); resolve(a.trim()) }) })

const inputs = page.locator('.login-form input')
await inputs.nth(0).fill(user)
await inputs.nth(1).fill(pass)
await inputs.nth(2).fill(ans)
await page.waitForTimeout(200)
await page.locator('.login-button, button:has-text("登录")').first().click()

await page.waitForFunction(() => !(window.location.hash || '').includes('/login'), { timeout: 40000 })
console.log('LOGIN OK hash=', await page.evaluate(() => window.location.hash))
await page.waitForTimeout(2500)
fs.writeFileSync(authPath, JSON.stringify(await ctx.storageState(), null, 2))
console.log('STORAGE saved')

// 进入单元管理列表
await page.goto('/#/projectManagement/unitinfo/index', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(3000)
await page.screenshot({ path: path.join(outDir, '6073-list.png') })
const rowCount = await page.locator('.el-table__body-wrapper tbody tr').count()
console.log('ROWS', rowCount)
if (!rowCount) { console.log('NO_ROWS'); await browser.close(); process.exit(0) }

// 打开第一行详情：优先「查看」
const firstRow = page.locator('.el-table__body-wrapper tbody tr').first()
const viewText = firstRow.getByText('查看', { exact: true })
if (await viewText.count()) {
  await viewText.first().click()
} else {
  const links = firstRow.locator('a, button')
  await links.first().click()
}
await page.waitForTimeout(3500)
console.log('DETAIL_HASH', await page.evaluate(() => window.location.hash))
await page.waitForTimeout(1500)

// 采集「房屋范围」工具栏：找到包含房屋选择/删除的那个按钮容器
const containers = await page.locator('.operation-button-container').all()
console.log('CONTAINER_COUNT', containers.length)
const buttonsAll = await page.locator('.operation-button-container button').allInnerTexts()
console.log('ALL_TOOLBAR_BUTTONS', JSON.stringify(buttonsAll.map((s) => s.replace(/\s+/g, '').trim())))

// 定位「房屋范围」headline 之后的容器
const scopeInfo = await page.evaluate(() => {
  const nodes = Array.from(document.querySelectorAll('div, section')).filter((el) => {
    const t = (el.textContent || '').trim()
    return el.children.length > 0 && t.startsWith('房屋范围') && t.length < 50
  })
  return nodes.map((el) => ({ text: el.textContent.replace(/\s+/g, ' ').trim().slice(0, 80), btns: Array.from(el.querySelectorAll('button')).map((b) => b.innerText.replace(/\s+/g, '').trim()) }))
    .filter((x) => x.btns.length || x.text.includes('房屋范围'))
    .slice(0, 6)
})
console.log('SCOPE_PROBE', JSON.stringify(scopeInfo))

const bodyText = await page.evaluate(() => document.body.innerText)
console.log('BODY_HAS_UNIT_SPLIT', bodyText.includes('单元拆分'))

await page.screenshot({ path: path.join(outDir, '6073-detail.png'), fullPage: true })
await browser.close()
console.log('DONE')

/**
 * bug 6073 端到端验证。
 * 关键改进：验证码图片与 uuid 必须在同一页面会话内使用，且识别耗时不能超过服务端有效期；
 * 因此本脚本用「长等待 + 终端交互」模式：打开登录页 → 截图存盘 → 停在同一个 page 上等人工输入答案
 * （浏览器内核保持运行，uuid 仍有效）→ 填表提交 → 进入单元详情采集「房屋范围」工具栏按钮。
 *
 * 运行： node e2e/scripts/verify6073-final.mjs
 */
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import readline from 'readline'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const authPath = path.resolve(__dirname, '../.auth/zsbase-auto.json')
const outDir = path.resolve(__dirname, '../../../.pua/shots')
fs.mkdirSync(outDir, { recursive: true })

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const user = process.env.PLAYWRIGHT_LOGIN_USER || 'zsbase'
const pass = process.env.PLAYWRIGHT_LOGIN_PASSWORD || 'ZS001Aa!'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')
const answerFromEnv = process.env.CAPTCHA_ANSWER || ''

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1680, height: 1000 } })
const page = await ctx.newPage()
page.setDefaultTimeout(30000)

page.on('response', async (r) => {
  const u = r.url()
  if (u.includes('userLogin')) { try { console.log('LOGIN_RESP', (await r.text()).slice(0, 160)) } catch {} }
})

await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.login-form input', { timeout: 30000 })
await page.waitForTimeout(2500)

const liveCap = path.join(outDir, 'live-captcha.png')
await page.locator('.login-code img').screenshot({ path: liveCap })
console.log('LIVE_CAPTCHA', liveCap)

let ans = answerFromEnv
if (!ans) {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
  ans = await new Promise((resolve) => { rl.question('INPUT_CAPTCHA> ', (a) => { rl.close(); resolve(a.trim()) }) })
}

const inputs = page.locator('.login-form input')
await inputs.nth(0).fill(user)
await inputs.nth(1).fill(pass)
await inputs.nth(2).fill(ans)
await page.waitForTimeout(250)
await page.locator('.login-button, button:has-text("登录")').first().click()

await page.waitForFunction(() => !(window.location.hash || '').includes('/login'), { timeout: 45000 })
console.log('LOGIN OK hash=', await page.evaluate(() => window.location.hash))
await page.waitForTimeout(2500)
fs.writeFileSync(authPath, JSON.stringify(await ctx.storageState(), null, 2))
console.log('STORAGE saved')

await page.goto('/#/projectManagement/unitinfo/index', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(3200)
await page.screenshot({ path: path.join(outDir, '6073-list.png') })
const rowCount = await page.locator('.el-table__body-wrapper tbody tr').count()
console.log('ROWS', rowCount)
if (!rowCount) { console.log('NO_ROWS'); await browser.close(); process.exit(0) }

const firstRow = page.locator('.el-table__body-wrapper tbody tr').first()
const viewText = firstRow.getByText('查看', { exact: true })
if (await viewText.count()) await viewText.first().click()
else await firstRow.locator('a, button').first().click()
await page.waitForTimeout(4000)
console.log('DETAIL_HASH', await page.evaluate(() => window.location.hash))
await page.waitForTimeout(1200)

const buttonsAll = await page.locator('.operation-button-container button').allInnerTexts()
console.log('ALL_TOOLBAR_BUTTONS', JSON.stringify(buttonsAll.map((s) => s.replace(/\s+/g, '').trim())))

const scopeProbe = await page.evaluate(() => {
  const out = []
  document.querySelectorAll('*').forEach((el) => {
    if (el.children.length && (el.textContent || '').trim().startsWith('房屋范围')) {
      const t = (el.textContent || '').replace(/\s+/g, ' ')
      if (t.length < 2000) {
        const btns = Array.from(el.querySelectorAll('button')).map((b) => b.innerText.replace(/\s+/g, '').trim())
        if (btns.length) out.push({ btns })
      }
    }
  })
  return out.slice(0, 5)
})
console.log('SCOPE_BUTTONS', JSON.stringify(scopeProbe))

const bodyText = await page.evaluate(() => document.body.innerText)
console.log('BODY_HAS_UNIT_SPLIT', bodyText.includes('单元拆分'))
await page.screenshot({ path: path.join(outDir, '6073-detail.png'), fullPage: true })
await browser.close()
console.log('DONE')

