await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.login-form input', { timeout: 30000 })
await page.waitForTimeout(2500)

const info = await page.evaluate(() => {
  const out = {}
  const code = document.querySelector('.login-code img')
  out.codeSrcPrefix = code ? String(code.getAttribute('src')).slice(0, 30) : 'none'
  out.inputs = Array.from(document.querySelectorAll('.login-form input')).map((i) => ({
    type: i.type, name: i.name, id: i.id, placeholder: i.placeholder, value: i.value
  }))
  out.loginButtonText = Array.from(document.querySelectorAll('.login-button, button')).map((b) => b.innerText.replace(/\s+/g, '')).filter(Boolean).slice(0, 6)
  return out
})
console.log(JSON.stringify(info, null, 2))

// 抓取 /code 的响应，确认 uuid；再在页面里注入观察 window 上的 loginForm 是否可访问
const resp = await page.evaluate(async () => {
  const r = await fetch('/api/v3.0/code', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
  const j = await r.json()
  return { hasData: !!j.data, dataLen: (j.data || '').length, uuid: j.uuid, code: j.code }
})
console.log('FETCH_CODE', JSON.stringify(resp))
await browser.close()

