/**
 * bug 6073 端到端验证（自洽版本）。
 * 为什么不再跨进程传答案：登录验证码 uuid 与图片取自同一响应，且页面每次进入/getCode 都会换新。
 * 本脚本一次性完成：打开登录页 -> 等验证码渲染 -> 把「当前这张图」存盘 -> 停下来等人工输入 ->
 * 立刻用页面上的 uuid 提交，全程同一页面、同一 uuid，避免图片与 uuid 错配。
 */
import { chromium } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const outDir = path.resolve(__dirname, '../../../.pua/shots')
fs.mkdirSync(outDir, { recursive: true })

const baseURL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8099'
const user = process.env.PLAYWRIGHT_LOGIN_USER || 'zsbase'
const pass = process.env.PLAYWRIGHT_LOGIN_PASSWORD || 'ZS001Aa!'
const exe = process.env.PW_CHROME_PATH || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright', 'chromium-1243', 'chrome-win64', 'chrome.exe')

const answerFile = path.join(outDir, 'captcha-answer.txt')
const holdFile = path.join(outDir, 'captcha-hold.flag')
try { fs.unlinkSync(answerFile) } catch {}
try { fs.unlinkSync(holdFile) } catch {}

const browser = await chromium.launch({ headless: true, executablePath: exe })
const ctx = await browser.newContext({ baseURL, viewport: { width: 1680, height: 1000 } })
const page = await ctx.newPage()
page.setDefaultTimeout(30000)

await page.goto('/#/login', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.login-code img', { timeout: 30000 })
await page.waitForTimeout(2500)

const liveCap = path.join(outDir, 'live-captcha.png')
await page.locator('.login-code img').screenshot({ path: liveCap })
fs.writeFileSync(holdFile, '1')
console.log('LIVE_CAPTCHA', liveCap)
console.log('WAITING_FOR_ANSWER_FILE', answerFile)

// 轮询等答案文件出现（最多 8 分钟）
const deadline = Date.now() + 8 * 60 * 1000
let ans = ''
while (Date.now() < deadline) {
  if (fs.existsSync(answerFile)) {
    ans = String(fs.readFileSync(answerFile, 'utf8')).trim()
    if (ans) break
  }
  await page.waitForTimeout(1000)
}
if (!ans) { console.log('NO_ANSWER_TIMEOUT'); await browser.close(); process.exit(0) }
console.log('GOT_ANSWER', ans)

const inputs = page.locator('.login-form input')
await inputs.nth(0).fill(user)
await inputs.nth(1).fill(pass)
await inputs.nth(2).fill(ans)
await page.waitForTimeout(250)
await page.locator('.login-button').first().click()

try {
  await page.waitForFunction(() => !(window.location.hash || '').includes('/login'), { timeout: 45000 })
} catch {
  console.log('LOGIN_FAILED')
  fs.writeFileSync(path.join(outDir, 'login-result.txt'), 'FAILED')
  await browser.close()
  process.exit(0)
}
console.log('LOGIN OK', await page.evaluate(() => window.location.hash))
await page.waitForTimeout(2500)
fs.writeFileSync(path.join(__dirname, '../.auth/zsbase-auto.json'), JSON.stringify(await ctx.storageState(), null, 2))

await page.goto('/#/projectManagement/unitinfo/index', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(3200)
await page.screenshot({ path: path.join(outDir, '6073-list.png') })
const rows = await page.locator('.el-table__body-wrapper tbody tr').count()
console.log('ROWS', rows)
if (rows) {
  const firstRow = page.locator('.el-table__body-wrapper tbody tr').first()
  const view = firstRow.getByText('查看', { exact: true })
  if (await view.count()) await view.first().click()
  else await firstRow.locator('a, button').first().click()
  await page.waitForTimeout(4200)
  console.log('DETAIL_HASH', await page.evaluate(() => window.location.hash))
  const btns = await page.locator('.operation-button-container button').allInnerTexts()
  console.log('TOOLBAR_BUTTONS', JSON.stringify(btns.map((s) => s.replace(/\s+/g, '').trim())))
  const bodyText = await page.evaluate(() => document.body.innerText)
  console.log('BODY_HAS_UNIT_SPLIT', bodyText.includes('单元拆分'))
  await page.screenshot({ path: path.join(outDir, '6073-detail.png'), fullPage: true })
  fs.writeFileSync(path.join(outDir, 'login-result.txt'), JSON.stringify({
    rows, hash: await page.evaluate(() => window.location.hash),
    toolbar: btns.map((s) => s.replace(/\s+/g, '').trim()),
    bodyHasUnitSplit: bodyText.includes('单元拆分')
  }, null, 2))
}
await browser.close()
console.log('DONE')
